from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class CellUnblock(OperationPrototype):
    def __init__(self, bts):
        super(CellUnblock, self).__init__(bts)
        self.bts.set_up_parent_rmods_for_cells()
        self.operation_details = {
            "Timeout": 0,
            "Operation": "Cell Unblock",
            "Start point": "Unblock cell request",
            "End point": "Cell up",
            "Requirement": "OM_GEN_SFS_PERF_CAP.13256",
        }

    def get_kpi(self, cell_dist_name):
        """
        Gets kpi for cell unblock operation.
        :param cell_dist_name: dist_name of the cell, which KPI cell unblock timeout will be applied to
        :type cell_dist_name: str
        :return: dictionary with timeout, requirement and operation description for cell unblock
        :rtype: dict
        """
        self.operation_details["Timeout"] = 10 + self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_13258(
            cell_dist_name)
        return self.operation_details
